#!/usr/bin/env bash
# TEAM CODE (owner: Tom - sound output and effects) - written by the BJT2 team, not generated by STM32CubeMX.
set -euo pipefail

find_llvm_tool() {
    local tool="$1"
    if command -v "$tool" >/dev/null 2>&1; then
        command -v "$tool"
    elif command -v xcrun >/dev/null 2>&1; then
        xcrun --find "$tool"
    else
        return 1
    fi
}

LLVM_PROFDATA="$(find_llvm_tool llvm-profdata)" || {
    echo "llvm-profdata not found. Install/use Xcode command-line tools." >&2
    exit 1
}
LLVM_COV="$(find_llvm_tool llvm-cov)" || {
    echo "llvm-cov not found. Install/use Xcode command-line tools." >&2
    exit 1
}

cmake --preset coverage-macos
cmake --build --preset coverage-macos

ROOT_DIR="$PWD"
PROFILE_DIR="$ROOT_DIR/build/coverage-macos/profiles"
HTML_DIR="$ROOT_DIR/build/coverage-macos/coverage-html"
rm -rf "$PROFILE_DIR" "$HTML_DIR"
mkdir -p "$PROFILE_DIR"

LLVM_PROFILE_FILE="$PROFILE_DIR/%p-%m.profraw" \
    ctest --preset coverage-macos --output-on-failure

"$LLVM_PROFDATA" merge -sparse "$PROFILE_DIR"/*.profraw \
    -o "$ROOT_DIR/build/coverage-macos/coverage.profdata"

COMMON_ARGS=(
    "$ROOT_DIR/build/coverage-macos/test_audio_effects"
    -object "$ROOT_DIR/build/coverage-macos/test_audio_effects_orchestration"
    -instr-profile="$ROOT_DIR/build/coverage-macos/coverage.profdata"
    -ignore-filename-regex='Tests/|Tools/'
)

echo
echo "=== Application coverage summary ==="
"$LLVM_COV" report "${COMMON_ARGS[@]}"

"$LLVM_COV" show "${COMMON_ARGS[@]}" \
    -format=html \
    -output-dir="$HTML_DIR"

echo
echo "HTML coverage report: $HTML_DIR/index.html"
